    return res

def process_dataset(c: int, w: int, points: List[Tuple[int, int]], connections: List[Tuple[int, int]]):
    G = nx.Graph()
    idx_points = {t:i for i,t in enumerate(points, 1)}
    G.add_nodes_from(idx_points.values(), pos=idx_points)
    G.add_edges_from((idx_points[s], idx_points[t])  for s, t in connections)

    shortest_path_lengths = dict(nx.shortest_path_length(G))

    path_lengths = []
